import{_ as d,O as n,P as l,Q as e,a3 as i,U as t,a4 as o,F as r}from"./framework-ef522221.js";const s={},c=o(`<h1 id="ai-switch-ai-编程工具配置同步插件" tabindex="-1"><a class="header-anchor" href="#ai-switch-ai-编程工具配置同步插件" aria-hidden="true">#</a> AI Switch - AI 编程工具配置同步插件</h1><p>把本地 AI 编程工具的配置文件同步成 Markdown 快照存进你的 Vault，随时查看、多机器同步、一键回写。</p><h2 id="为什么开发这个插件" tabindex="-1"><a class="header-anchor" href="#为什么开发这个插件" aria-hidden="true">#</a> 为什么开发这个插件？</h2><p>现在用 AI 编程工具的人越来越多，Codex、Claude Code、OpenCode 等工具各有各的配置文件，散落在系统的不同目录里。日常使用中我遇到了这些痛点：</p><ul><li><strong>配置分散</strong>：<code>~/.codex/config.toml</code>、<code>~/.claude/settings.json</code>、<code>~/.config/opencode</code> 各管各的，想统一查看很麻烦</li><li><strong>多机器同步</strong>：公司电脑、家里电脑、笔记本，每台机器都要重新配置一遍，改了一台忘了另一台</li><li><strong>无法追踪</strong>：改了配置之后不知道改了什么，没有历史记录，回退困难</li><li><strong>新手门槛高</strong>：刚接触 AI 编程工具时，不知道这些配置文件在哪、长什么样</li></ul><p>为了解决这些问题，我开发了 AI Switch。它把这些配置文件读取出来，转成 Markdown 快照存进 Obsidian Vault，让配置管理变得简单透明。</p><h2 id="核心功能" tabindex="-1"><a class="header-anchor" href="#核心功能" aria-hidden="true">#</a> 核心功能</h2><h3 id="📸-配置快照同步" tabindex="-1"><a class="header-anchor" href="#📸-配置快照同步" aria-hidden="true">#</a> 📸 配置快照同步</h3><ul><li><strong>一键同步</strong>：点击侧边栏按钮，自动读取本地 AI 工具配置</li><li><strong>Markdown 快照</strong>：把配置文件内容存成 <code>.md</code> 文件，方便阅读和对比</li><li><strong>自动分组</strong>：按机器名和工具类型自动归类，结构清晰</li></ul><p>快照目录结构如下：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Config Manager/
└── zhang_aifende_macbook-air/
    ├── codex/
    │   └── config.toml.md
    ├── claude/
    │   └── settings.json.md
    └── opencode/
        └── opencode.json.md
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="🔄-双向同步" tabindex="-1"><a class="header-anchor" href="#🔄-双向同步" aria-hidden="true">#</a> 🔄 双向同步</h3><ul><li><strong>Sync to note</strong>：把本地配置读取到 Vault 中</li><li><strong>Apply to local</strong>：把 Vault 中的快照回写到本地配置文件</li><li><strong>安全回写</strong>：回写前会弹窗确认，并自动创建带时间戳的备份文件，不怕误操作</li></ul><h3 id="🖥️-多机器管理" tabindex="-1"><a class="header-anchor" href="#🖥️-多机器管理" aria-hidden="true">#</a> 🖥️ 多机器管理</h3><ul><li><strong>自动识别</strong>：根据机器名自动创建子目录，不同机器的配置互不干扰</li><li><strong>集中查看</strong>：所有机器的配置都在同一个 Vault 里，一目了然</li><li><strong>Git 同步</strong>：配合 Obsidian Git 插件，配置变更自动同步到所有设备</li></ul><h3 id="📁-灵活的文件源" tabindex="-1"><a class="header-anchor" href="#📁-灵活的文件源" aria-hidden="true">#</a> 📁 灵活的文件源</h3><ul><li><strong>预设工具</strong>：内置 Codex、Claude、OpenCode 三个常用工具的默认路径</li><li><strong>文件夹导入</strong>：支持递归导入 <code>.toml</code>、<code>.json</code>、<code>.yaml</code>、<code>.yml</code> 文件</li><li><strong>自定义路径</strong>：配置文件不在默认位置？在设置里改路径即可</li><li><strong>自动跳过</strong>：路径不存在时自动跳过，不会报错</li></ul><h2 id="使用方法" tabindex="-1"><a class="header-anchor" href="#使用方法" aria-hidden="true">#</a> 使用方法</h2><h3 id="安装" tabindex="-1"><a class="header-anchor" href="#安装" aria-hidden="true">#</a> 安装</h3><ol><li>从 GitHub Release 下载 <code>main.js</code>、<code>manifest.json</code>、<code>styles.css</code></li><li>复制到 Obsidian Vault 的 <code>.obsidian/plugins/ai-switch/</code> 目录</li><li>在 Obsidian 设置中启用插件</li></ol><h3 id="基本操作" tabindex="-1"><a class="header-anchor" href="#基本操作" aria-hidden="true">#</a> 基本操作</h3><ol><li><strong>启用插件</strong>：安装后在设置中开启 AI Switch</li><li><strong>选择工具</strong>：在设置里勾选需要同步的工具（Codex / Claude / OpenCode）</li><li><strong>打开侧边栏</strong>：点击左侧边栏的 AI Switch 图标</li><li><strong>同步配置</strong>：点击 <code>Sync to note</code> 读取本地配置到 Vault</li><li><strong>回写配置</strong>：编辑快照后点击 <code>Apply to local</code> 写回本地（会自动备份）</li></ol><h3 id="配置项" tabindex="-1"><a class="header-anchor" href="#配置项" aria-hidden="true">#</a> 配置项</h3><p>在 <strong>设置 → AI Switch</strong> 中：</p><table><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>Config root folder</td><td>快照存放的根目录，默认 <code>Config Manager</code></td></tr><tr><td>Codex</td><td>同步 <code>~/.codex/config.toml</code></td></tr><tr><td>Claude</td><td>同步 <code>~/.claude/settings.json</code></td></tr><tr><td>OpenCode</td><td>同步 <code>~/.config/opencode</code></td></tr></tbody></table><p>每个工具的路径都可以自定义，适配你的实际安装位置。</p><h2 id="典型场景" tabindex="-1"><a class="header-anchor" href="#典型场景" aria-hidden="true">#</a> 典型场景</h2><h3 id="场景一-多机器配置同步" tabindex="-1"><a class="header-anchor" href="#场景一-多机器配置同步" aria-hidden="true">#</a> 场景一：多机器配置同步</h3><p>你在公司电脑上调好了 Codex 的模型配置，想在家里电脑用同样的配置：</p><ol><li>公司电脑上点击 <code>Sync to note</code>，配置快照存入 Vault</li><li>Vault 通过 Git 同步到家里电脑</li><li>家里电脑上点击 <code>Apply to local</code>，一键应用配置</li></ol><h3 id="场景二-配置版本管理" tabindex="-1"><a class="header-anchor" href="#场景二-配置版本管理" aria-hidden="true">#</a> 场景二：配置版本管理</h3><p>你修改了 Claude Code 的设置，改完发现不对想回退：</p><ol><li>每次同步都会覆盖快照，配合 Obsidian Git 可以看到配置的变更历史</li><li><code>Apply to local</code> 会自动创建备份，随时可以回退</li></ol><h3 id="场景三-团队配置共享" tabindex="-1"><a class="header-anchor" href="#场景三-团队配置共享" aria-hidden="true">#</a> 场景三：团队配置共享</h3><p>团队成员想统一 AI 工具的配置标准：</p><ol><li>把快照目录放进共享 Vault</li><li>每个人都能看到标准配置长什么样</li><li>需要时 <code>Apply to local</code> 一键应用</li></ol><h2 id="安全说明" tabindex="-1"><a class="header-anchor" href="#安全说明" aria-hidden="true">#</a> 安全说明</h2><p>AI Switch 在设计上把安全放在第一位：</p><ul><li><strong>只读系统目录</strong>：同步时只读取本地配置文件，不修改</li><li><strong>回写需确认</strong>：<code>Apply to local</code> 操作会弹窗确认</li><li><strong>自动备份</strong>：每次回写前自动创建带时间戳的备份文件</li><li><strong>本地操作</strong>：所有操作都在本地完成，不上传任何数据</li></ul><h2 id="技术栈" tabindex="-1"><a class="header-anchor" href="#技术栈" aria-hidden="true">#</a> 技术栈</h2><ul><li><strong>TypeScript</strong>：类型安全的开发体验</li><li><strong>Obsidian API</strong>：深度集成 Vault 文件系统</li><li><strong>ESBuild</strong>：快速构建</li></ul><h2 id="下载地址" tabindex="-1"><a class="header-anchor" href="#下载地址" aria-hidden="true">#</a> 下载地址</h2>`,42),h=e("strong",null,"GitHub",-1),g={href:"https://github.com/fengshuzi/ai-switch",target:"_blank",rel:"noopener noreferrer"},u=e("strong",null,"社区插件页",-1),p={href:"https://community.obsidian.md/plugins/ai-switch",target:"_blank",rel:"noopener noreferrer"},b=o('<h2 id="路线图" tabindex="-1"><a class="header-anchor" href="#路线图" aria-hidden="true">#</a> 路线图</h2><p>AI Switch 目前是一个配置快照同步工具，后续计划：</p><ul><li>🎯 内置常用 AI 编程工具的模型/服务商预设</li><li>🎯 帮助新手安全地切换模型配置</li><li>🎯 提供更完善的配置回写流程</li></ul><h2 id="许可证" tabindex="-1"><a class="header-anchor" href="#许可证" aria-hidden="true">#</a> 许可证</h2><p>MIT</p><hr><p><strong>🤖 让 AI 编程工具的配置管理变得简单透明！</strong></p>',7);function f(m,x){const a=r("ExternalLinkIcon");return n(),l("div",null,[c,e("ul",null,[e("li",null,[h,i(": "),e("a",g,[i("https://github.com/fengshuzi/ai-switch"),t(a)])]),e("li",null,[u,i(": "),e("a",p,[i("https://community.obsidian.md/plugins/ai-switch"),t(a)])])]),b])}const v=d(s,[["render",f],["__file","obsidian-ai-switch.html.vue"]]);export{v as default};
